L000066	\title{Mean-field approach to finite-size fluctuations in the Kuramoto-Sakaguchi model}
L000067	
L000068	\author{Oleh E. Omel'chenko}
L000069	\email{omelchenko@uni-potsdam.de}
L000070	\address{University of Potsdam,
