L000610	\section{Thermodynamic limit for the KS model~(\ref{Eq:KS:original})}
L000611	\label{app:MFT}
L000612	
L000613	Most of the dynamical states found in the KS model~(\ref{Eq:KS:original}) with finite $N$, have complex chaotic behavior. However, in the thermodynamic limit $N\to\infty$, they admit a simple analytic representation. If $N\gg 1$, the state of the phase oscillators $\{\psi_i(t)\}$ can be described by a probability density function $f(\psi,\omega,t)$, which obeys the continuity equation
L000614	\begin{equation}
L000615	\pf{f}{t} + \pf{}{\psi}(f v) = 0,
L000616	\label{Eq:Continuity}
L000617	\end{equation}
L000618	where
L000619	$$
L000620	v(\psi,\omega,t) = \omega + \fr{K}{2i} \left[ e^{-i\lambda} \mathcal{Z} (t) e^{-i\psi} - e^{i \lambda} \overline{\mathcal{Z}}(t) e^{i \psi} \right]
L000621	$$
L000622	is the continuum version of the velocity field in Eq.~(\ref{Eq:KS:original}), and
L000623	\begin{equation}
L000624	\mathcal{Z}(t) = \int_{-\infty}^\infty d\omega \int_0^{2\pi} f(\psi,\omega,t) e^{i \psi} d\psi
L000625	\label{Def:W}
L000626	\end{equation}
L000627	is the continuum version of the complex order parameter~\eqref{Def:Z}.
L000628	
L000629	It is well-known~\cite{OttA2008,OttA2009} that the long-term dynamics of the continuity equation (\ref{Eq:Continuity}) asymptotically approaches the Ott-Antonsen manifold for $t\to\infty$, consisting of distributions of the form
L000630	$$
L000631	f(\psi,\omega,t) = \fr{g(\omega)}{2\pi} \left\{ 1 + \sum\limits_{n=1}^\infty
L000632	\left[ \overline{z}^n(\omega,t) e^{i n \psi} + z^n(\omega,t) e^{-i n \psi} \right] \right\},
L000633	$$
L000634	where $z(\omega,t)$ satisfies the inequality $|z|\le 1$
L000635	and solves the integro-differential equation
L000636	\begin{equation}
L000637	\pf{z}{t} = i \omega z(\omega,t) + \fr{K}{2} e^{-i\lambda} \mathcal{G}z - \fr{K}{2} e^{i \lambda} z^2(\omega,t) \mathcal{G}\overline{z}
L000638	\label{Eq:OA}
L000639	\end{equation}
L000640	with the integral operator
L000641	$$
L000642	(\mathcal{G} z)(t) = \int_{-\infty}^\infty g(\omega) z(\omega,t) d\omega.
L000643	$$
L000644	Remarkably, all statistically stationary states of the KS model~(\ref{Eq:KS:original}) lie on the Ott-Antonsen manifold~\cite{OmeW2012,OmeW2013}. In particular, the zero solution $z(\omega,t) = 0$ of Eq.~(\ref{Eq:OA}) corresponds to the completely incoherent state in~(\ref{Eq:KS:original}), while all stationary partially synchronized states in~(\ref{Eq:KS:original}) are represented by rotating waves
L000645	\begin{equation}
L000646	z(\omega,t) = h\left( \fr{\omega - \Omega_\infty}{K r_\infty} \right) e^{i \Omega_\infty t},
L000647	\label{Ansatz:Wave}
L000648	\end{equation}
L000649	where $h(s)$ is defined by~\eqref{Def:h} and $(r_\infty,\Omega_\infty)\in(0,1)\times\mathbb{R}$ is a pair of numbers satisfying the self-consistency equation~\eqref{Eq:SC}.
L000650	
L000651	The physical meaning of the parameters $r_\infty$ and $\Omega_\infty$ can be understood by inserting the probability density function $f(\psi,\omega,t)$ corresponding to~(\ref{Ansatz:Wave}) into Eq.~(\ref{Def:W}). This yields
L000652	\begin{equation}
L000653	\mathcal{Z}(t) = - r_\infty i e^{i \lambda} e^{i \Omega_\infty t},
L000654	\label{Z_infty}
L000655	\end{equation}
L000656	and therefore
L000657	\begin{equation}
L000658	|\mathcal{Z}(t)| = r_\infty
L000659	\label{Z_infty_}
L000660	\end{equation}
L000661	is the magnitude of the order parameter, while $\Omega_\infty$ is the angular speed of its phase.
L000662	
L000663	If in the KS model~(\ref{Eq:KS:original})
L000664	we move into the corotating frame
L000665	\begin{equation}
L000666	\theta_i(t) = \psi_i(t) - \Omega_\infty t + \phi
L000667	\quad\mbox{with some}\quad\phi\in\mathbb{R},
L000668	\label{Def:Frame:phi}
L000669	\end{equation}
L000670	the probability density function in the new frame will take on the time-independent form~\eqref{Def:f_phi}, which is used for the calculations in the main text.
L000671	Importantly, for an appropriately chosen value of $\phi$,
L000672	we can guarantee that (\ref{Z_mod:infty})
L000673	yields the thermodynamic limit of the modified order parameter $Z_\mathrm{mod}(t)$.
L000674	
L000675	
L000676	
L000677	
L000678	\section{Explicit solutions of the Adler equation}
L000679	\label{app:Adler}
L000680	
L000681	Let us consider the Adler equation written in complex form,
L000682	\begin{equation}
L000683	\dot{\theta} = \Delta + \Imag\left( H e^{-i \theta} \right)
L000684	= \Delta + \fr{H e^{-i \theta} - \overline{H} e^{i \theta}}{2i}
L000685	\label{Eq:Adler}
L000686	\end{equation}
L000687	with arbitrary $\Delta \in \mathbb{R}$ and $H\in \mathbb{C}$.
L000688	\begin{proposition}
L000689	If $|\Delta|\ne|H|$, the solution of the Adler equation (\ref{Eq:Adler}) is of the form
L000690	$$
L000691	e^{i \theta(t)} = W( t, H, \Delta, e^{i \theta(0)} )
L000692	:= \fr{ i H ( e^{i \xi t} - 1 ) - \chi_2(t) e^{i \theta(0)} }{ i \overline{H} ( e^{i \xi t} - 1 ) e^{i \theta(0)} + \chi_1(t) },
L000693	$$
L000694	where $\xi$ is defined in Eq. \eqref{Def:xi}, and
L000695	$$
L000696	\chi_1( t ) = (\Delta - \xi) e^{i \xi t} - (\Delta + \xi),
L000697	\quad
L000698	\chi_2( t ) = (\Delta + \xi) e^{i \xi t} - (\Delta - \xi).
L000699	$$
L000700	In addition, in the degenerate case $|\Delta|=|H|$, the solution of the Adler equation (\ref{Eq:Adler}) is given by
L000701	$$
L000702	e^{i \theta(t)} = W_0( t, H, \Delta, e^{i \theta(0)} )
L000703	:= z_* + \fr{e^{i \theta(0)} - z_*}{1 + ( e^{i \theta(0)} - z_* ) \overline{H} t / 2},
L000704	$$
L000705	where $z_* = i \Delta / H$. (For brevity of notation, we do not specify that $\xi$, $\chi_1(t)$, $\chi_2(t)$ and $z_*$ depend on $\Delta$ and $H$.)
L000706	\label{Prop:Adler}
L000707	\end{proposition}
L000708	
L000709	{\bf Proof:}
L000710	Multiplying Eq.~(\ref{Eq:Adler}) by $i e^{i \theta}$,
L000711	we obtain a complex differential equation for $z = e^{i \theta}$:
L000712	\begin{equation}
L000713	\dot{z} = \fr{1}{2} H + i \Delta z - \fr{1}{2} \overline{H} z^2.
L000714	\label{Eq:Adler:Complex}
L000715	\end{equation}
L000716	For $|\Delta|\ne |H|$, the right-hand side of this equation can be written as
L000717	$$
L000718	\fr{1}{2} H + i \Delta z - \fr{1}{2} \overline{H} z^2
L000719	= - \fr{1}{2} \overline{H} ( z - z_+ ) ( z - z_- ),
L000720	$$
L000721	where $z_\pm = i ( \Delta \pm \xi ) / \overline{H}$.
L000722	Using the method of separation of variables and the initial condition $z(0) = \sigma$, we obtain
L000723	$$
L000724	z(t) = \fr{z_+ ( \sigma - z_- ) e^{i \xi t} - z_- ( \sigma - z_+ )}{ ( \sigma - z_- ) e^{i \xi t} - ( \sigma - z_+ )},
L000725	$$
L000726	or equivalently $e^{i \theta(t)} = W( t, H, \Delta, e^{i \theta(0)} )$.
L000727	
L000728	In the degenerate case $|\Delta|=|H|$, we have $z_+ = z_- = z_*$. Integrating Eq.~(\ref{Eq:Adler:Complex}), we obtain $e^{i \theta(t)} = W_0( t, H, \Delta, e^{i \theta(0)} )$.
L000729	\qed
L000730	\\
L000731	
L000732	\begin{remark}
L000733	In the case $|\Delta| \ne |H|$, we can write
L000734	$$
L000735	W( t, H, \Delta, \sigma ) = H a_1(t) + \fr{a_2( t) \sigma}{1 + \overline{H} a_1( t) \sigma},
L000736	$$
L000737	with
L000738	$$
L000739	a_1(t) = \fr{i (e^{i \xi t} - 1)}{\chi_1(t)}
L000740	\quad\mbox{and}\quad
L000741	a_2(t) = \fr{4 \xi^2 e^{i \xi t}}{\chi_1^2(t)}.
L000742	$$
L000743	Moreover, in this case, we have $|H a_1(t)| < 1$, and hence
L000744	$$
L000745	W(t, H, \Delta, \sigma) = H a_1(t) + a_2(t) \sum\limits_{n=0}^\infty (-1)^n \overline{H}^n a_1^n(t) \sigma^{n+1}
L000746	$$
L000747	is an absolutely convergent series for $|\sigma|\le 1$.
L000748	\label{Remark:W}
L000749	\end{remark}
L000750	
L000751	\begin{remark}
L000752	If $(r_\infty,\Omega_\infty)\in(0,1)\times\mathbb{R}$ satisfy
L000753	the self-consistency equation~\eqref{Eq:SC}, it can be easily verified
L000754	that $z_\varphi(\omega)$ defined by~\eqref{Formula:zphi} is a fixed point
L000755	of the Adler equation~(\ref{Eq:Adler}) with $\Delta = \omega - \Omega_\infty$
L000756	and $H = - i K r_\infty e^{i \phi}$. Therefore,
L000757	$$
L000758	W\left(t, - i K r_\infty e^{i \phi}, \omega - \Omega_\infty, z_\phi(\omega) \right) = z_\phi(\omega)
L000759	$$
L000760	for all $t,\omega,\phi\in\mathbb{R}$.
L000761	\label{Remark:W_z0}
L000762	\end{remark}
L000763	
L000764	\begin{remark}
L000765	Under the assumptions of Remark~\ref{Remark:W_z0},
L000766	using Remark~\ref{Remark:W} and formula~\eqref{Formula:OA}, we can show
L000767	\begin{eqnarray*}
L000768	&&
L000769	\int_0^{2\pi} e^{i \theta} \overline{W}( t, H, \Delta, e^{i \theta} ) \fr{f_\phi(\theta,\omega)}{g(\omega)} d\theta
L000770	= \int_0^{2\pi} \left[ \overline{H a_1(t)} e^{i \theta} \vphantom{\sum\limits_{n=0}^\infty} \right. \\
L000771	&&
L000772	\left. + \overline{a_2(t)} \sum\limits_{n=0}^\infty (-1)^n H^n \overline{a_1^n(t)} e^{-i n \theta} \right]
L000773	\fr{f_\phi(\theta,\omega)}{g(\omega)} d\theta \\
L000774	&&
L000775	= \overline{H a_1(t)} z_\phi(\omega) + \overline{a_2(t)} \sum\limits_{n=0}^\infty (-1)^n H^n \overline{a_1^n(t)} \overline{z}_\phi^n(\omega) \\
L000776	&&
L000777	= \overline{H a_1(t)} \left( z_\phi(\omega) - \fr{1}{\overline{z_\phi(\omega)}} \right) + \fr{1}{\overline{z_\phi(\omega)}} \overline{W( t, H, \Delta, z_\phi(\omega) )} \\
L000778	&&
L000779	= \fr{\overline{H a_1(t)}}{\overline{z_\phi(\omega)}} ( |z_\phi(\omega)|^2 - 1 ) + 1.
L000780	\end{eqnarray*}
L000781	\label{Remark:Integral}
L000782	\end{remark}
