L000788	\section{Derivation of Eq.~\eqref{Formula:R:ps} from Eq.~\eqref{Formula:U1}}
L000789	\label{app:Derivation}
L000790	
L000791	Using~\eqref{Def:h} it is easy to verify that
L000792	\begin{equation}
L000793	|H|\,  h\left( \fr{\Delta}{|H|} \right) = \left\{
L000794	\begin{array}{lcl}
L000795	\Delta - \xi\:\mathrm{sgn}(\Delta) & \mbox{ for } & |\Delta| > |H|,\\[2mm]
L000796	\Delta + \xi & \mbox{ for } & |\Delta|\le |H|,
L000797	\end{array}
L000798	\right.
L000799	\label{Formula:H:h}
L000800	\end{equation}
L000801	where $\xi$ is given by~\eqref{Def:xi}.
L000802	Note that formula~\eqref{Formula:H:h} holds for all $\Delta\in\mathbb{R}$ and $H\in\mathbb{C}$.
L000803	
L000804	
L000805	\begin{figure*}
L000806	\begin{center}
L000807	\begin{overpic}
L000808	[width=0.32\textwidth,angle=0]{Gauss_zeta_Re_K3p0.png}
L000809	     \put(47,-7){\small (a)}
L000810	\end{overpic}
L000811	\begin{overpic}
L000812	[width=0.32\textwidth,angle=0]{Gauss_zeta_Im_K3p0.png}
L000813	     \put(47,-7){\small (b)}
L000814	\end{overpic}\begin{overpic}
L000815	[width=0.32\textwidth,angle=0]{Gauss_dpsic_K3p0.png}
L000816	     \put(47,-7){\small (c)}
L000817	\end{overpic}
L000818	\end{center}
L000819	\caption{
L000820	Empirical histograms of the real (a) and imaginary (b) part of the fluctuations $\zeta$
L000821	and of $d[{\rm{arg}}Z_\mathrm{c}(t)]/dt$ centered around $\Omega_\infty\approx -1.71$
L000822	(c) for the KS model (\ref{Eq:KS:original}) with $N=1,000$ oscillators,
L000823	phase lag $\lambda=\pi/4$, and $K=3$.
L000824	The continuous lines (online red) show a best-fit Gaussian with the same variance.
L000825	}
L000826	\label{Fig:Gaussianity}
L000827	\end{figure*}
L000828	
L000829	Now, we consider the integrand of Eq.~\eqref{Formula:U1},
L000830	recalling that $H = K Z_\infty e^{-i \lambda} = - i K r_\infty e^{i \phi}$.
L000831	Recognizing that in this case
L000832	$$
L000833	\fr{H}{z_\phi(\omega)} = - \fr{i K r_\infty e^{i \phi}}{e^{i \phi} h\left(\fr{\omega-\Omega_\infty}{K r_\infty}\right)}
L000834	= - \fr{i |H|}{h\left(\fr{\Delta}{|H|}\right)}
L000835	$$
L000836	does not depend on $\phi$, we find
L000837	\begin{eqnarray}
L000838	&&
L000839	\fr{H a_1(\tau)}{z_\phi(\omega)} - 1 =
L000840	- \fr{i |H|}{h\left(\fr{\Delta}{|H|}\right)} \fr{i (e^{i \xi t} - 1)}{\chi_1(t)} - 1 \nonumber\\[2mm]
L000841	&&
L000842	=
L000843	\fr{|H|^2}{|H| h\left(\fr{\Delta}{|H|}\right)} \fr{e^{i \xi t} - 1}{(\Delta - \xi) e^{i \xi t} - (\Delta + \xi)} - 1.
L000844	\label{Formula:H:a:z_phi}
L000845	\end{eqnarray}
L000846	For $\Delta > |H|$, upon using~\eqref{Formula:H:h} and the identity $\Delta^2 - \xi^2 = |H|^2$,
L000847	\eqref{Formula:H:a:z_phi} is written as
L000848	\begin{eqnarray*}
L000849	&&
L000850	\fr{H a_1(\tau)}{z_\phi(\omega)} - 1 =
L000851	\fr{|H|^2 ( e^{i \xi t} - 1 )}{(\Delta - \xi)^2 e^{i \xi t} - (\Delta + \xi) (\Delta - \xi)} - 1 \\[2mm]
L000852	&&
L000853	= \fr{e^{i \xi t} - 1}{h^2(\Delta/|H|) e^{i \xi t} - 1} - 1
L000854	= \fr{1 - h^2(\Delta/|H|)}{h^2(\Delta/|H|) - e^{-i \xi t}}.
L000855	\end{eqnarray*}
L000856	Similarly, for $\Delta \le |H|$ we obtain
L000857	$$
L000858	\fr{H a_1(\tau)}{z_\phi(\omega)} - 1
L000859	= \fr{1 - h^2(\Delta/|H|)}{h^2(\Delta/|H|) - e^{i \xi t}},
L000860	$$
L000861	and thus in both cases we have
L000862	$$
L000863	\fr{H a_1(\tau)}{z_\phi(\omega)} - 1
L000864	= \fr{1 - h^2(\Delta/|H|)}{h^2(\Delta/|H|) - e^{-i \Delta \sqrt{1 - |H|^2/\Delta^2} t}}.
L000865	$$
L000866	Substituting into Eq.~\eqref{Formula:U1}, we obtain Eq.~\eqref{Formula:R:ps}.
