L000871	\section{Pseudo-covariance function for a partially synchronized state}
L000872	\label{app:Pseudocov}
L000873	
L000874	Using the definition of the pseudo-covariance function $\tilde R_{\rm{ps}}(t) = \langle \zeta(t) \zeta(t+\tau) \rangle$
L000875	and employing the established independence of the functions $e^{i \theta_j(t)}$ and $e^{i \theta_k(t)}$ for $j\ne k$,
L000876	by analogy with \eqref{Formula:R:ps2}, we obtain
L000877	$$
L000878	\tilde{R}_\mathrm{ps}(\tau) = \frac{1}{N}
L000879	\sum\limits_{j\in\mathcal{R}} \langle e^{i \theta_j(t)} e^{i \theta_j(t+\tau)} \rangle
L000880	- \frac{1}{N}
L000881	\sum\limits_{j\in\mathcal{R}} \langle e^{i \theta_j(t)} \rangle^2.
L000882	$$
L000883	Using the ergodicity property~\eqref{Ergodicity}
L000884	and performing calculations as in Remark~\ref{Remark:Integral}, we find
L000885	\begin{eqnarray*}
L000886	&&
L000887	\langle e^{i \theta_j(t)} e^{i \theta_j(t+\tau)} \rangle
L000888	=
L000889	\int\limits_0^{2\pi} e^{i \theta} W( \tau, H_\infty,\Delta_j, e^{i \theta} ) \fr{f_\phi(\theta,\omega_j)}{g(\omega_j)} d\theta \\
L000890	&&
L000891	= z_\phi(\omega_j) W( \tau, H_\infty, \Delta_j, z_\phi(\omega_j) ) = z_\phi^2(\omega_j).
L000892	\end{eqnarray*}
L000893	Recalling that $\langle e^{i \theta_j(t)} \rangle = z_\phi(\omega_j)$,
L000894	we obtain $\tilde{R}_\mathrm{ps}(\tau) = 0$.
L000895	Note that this relation is valid regardless of the choice of $\phi$
L000896	in the definition of the corotating frame~\eqref{Def:Frame:phi}.
