L001347	\section{Pairwise covariances of rogue oscillators}
L001348	\label{app:indep}
L001349	In Proposition~\ref{Prop:Adler}, we derived an explicit formula
L001350	for the solutions of the Adler equation~(\ref{Eq:Adler}).
L001351	Simple calculations show that this formula has the equivalent form
L001352	$$
L001353	e^{i \theta(t)} e^{- i \theta(0)}
L001354	= \fr{ \chi_+ e^{i \xi t} - \chi_- }{- \overline{\chi}_- e^{i \xi t} + \overline{\chi}_+}
L001355	= \fr{ \chi_+ - \chi_- e^{-i \xi t} }{- \overline{\chi}_- + \overline{\chi}_+ e^{-i \xi t}},
L001356	$$
L001357	where
L001358	$$
L001359	\chi_- = i H e^{- i \theta(0)} - ( \Delta - \xi ),\quad
L001360	\chi_+ = i H e^{- i \theta(0)} - ( \Delta + \xi ).
L001361	$$
L001362	We use this form to justify the following statements.
L001363	
L001364	\begin{proposition}
L001365	If $\Delta > |H|$, we have $| \chi_- / \chi_+ | < 1$
L001366	and the following expansion holds
L001367	\begin{eqnarray}
L001368	e^{i \theta(t)}
L001369	&=& - \fr{\chi_-}{\overline{\chi}_+} e^{i \theta(0)}
L001370	+ \fr{ |\chi_+|^2 - |\chi_-|^2 }{ \overline{\chi}_+ \overline{\chi}_- } e^{i \theta(0)}
L001371	\sum\limits_{n=1}^\infty \left( \fr{\overline{\chi}_-}{\overline{\chi}_+} \right)^n e^{i n \xi t}
L001372	\nonumber\\[2mm]
L001373	&=& \left\langle e^{i \theta(t)} \right\rangle - \fr{2 i \xi}{\overline{H}}
L001374	\sum\limits_{n=1}^\infty \left( \fr{i \overline{H} e^{i \theta(0)} + \Delta - \xi}{i \overline{H} e^{i \theta(0)} + \Delta + \xi} \right)^n e^{i n \xi t},
L001375	\label{Formula:exp_theta:plus}
L001376	\end{eqnarray}
L001377	where $\left\langle e^{i \theta(t)} \right\rangle$
L001378	denotes the time average of $e^{i \theta(t)}$.
L001379	On the other hand, if $\Delta < - |H|$, then $| \chi_+ / \chi_- | < 1$ and
L001380	\begin{eqnarray*}
L001381	e^{i \theta(t)}
L001382	&=& - \fr{\chi_+}{\overline{\chi}_-} e^{i \theta(0)}
L001383	+ \fr{ |\chi_-|^2 - |\chi_+|^2 }{ \overline{\chi}_+ \overline{\chi}_- } e^{i \theta(0)}
L001384	\sum\limits_{n=1}^\infty \left( \fr{\overline{\chi}_+}{\overline{\chi}_-} \right)^n e^{-i n \xi t} \\[2mm]
L001385	&=& \left\langle e^{i \theta(t)} \right\rangle + \fr{2 i \xi}{\overline{H}}
L001386	\sum\limits_{n=1}^\infty \left( \fr{i \overline{H} e^{i \theta(0)} + \Delta + \xi}{i \overline{H} e^{i \theta(0)} + \Delta - \xi} \right)^n e^{-i n \xi t}.
L001387	\end{eqnarray*}
L001388	\label{Proposition:Expansions}
L001389	\end{proposition}
L001390	
L001391	{\bf Proof:} For brevity, we denote $\zeta = i H e^{- i \theta(0)}$.
L001392	Then $e^{i \theta(0)} = i \overline{\zeta} / \overline{H}$.
L001393	Next, using the definition $\xi = \sqrt{ \Delta^2 - |H|^2 }$, we obtain
L001394	\begin{eqnarray*}
L001395	| \chi_+ |^2 &=& ( \zeta - \Delta - \xi ) ( \overline{\zeta} - \Delta - \xi ) \\[2mm]
L001396	&=& ( \Delta + \xi ) ( 2 \Delta - \zeta - \overline{\zeta} ),\\[2mm]
L001397	| \chi_- |^2 &=& ( \zeta - \Delta + \xi ) ( \overline{\zeta} - \Delta + \xi ) \\[2mm]
L001398	&=& ( \Delta - \xi ) ( 2 \Delta - \zeta - \overline{\zeta} ),
L001399	\end{eqnarray*}
L001400	and
L001401	\begin{eqnarray*}
L001402	\left( |\chi_+|^2 - |\chi_-|^2 \right) e^{i \theta(0)} &=&
L001403	2 \xi ( 2 \Delta - \zeta - \overline{\zeta} ) i \overline{\zeta} / \overline{H} \\[2mm]
L001404	&=& - 2 i \xi ( \overline{\zeta}^2 - 2 \Delta \overline{\zeta} + |H|^2 ) / \overline{H},\\[2mm]
L001405	\overline{\chi}_+ \overline{\chi}_- &=&
L001406	( \overline{\zeta} - \Delta - \xi ) ( \overline{\zeta} - \Delta + \xi ) \\[2mm]
L001407	&=& \overline{\zeta}^2 - 2 \Delta \overline{\zeta} + |H|^2.
L001408	\end{eqnarray*}
L001409	Therefore,
L001410	$$
L001411	\fr{ |\chi_+|^2 - |\chi_-|^2 }{ \overline{\chi}_+ \overline{\chi}_- } e^{i \theta(0)}
L001412	= -\fr{2 i \xi}{\overline{H}}.
L001413	$$
L001414	On the other hand, we have
L001415	$$
L001416	\fr{\overline{\chi}_-}{\overline{\chi}_+} = \fr{\overline{\zeta} - \Delta + \xi}{\overline{\zeta} - \Delta - \xi} = \fr{i \overline{H} e^{i \theta(0)} + \Delta - \xi}{i \overline{H} e^{i \theta(0)} + \Delta + \xi}.
L001417	$$
L001418	Summarizing, this gives formula~(\ref{Formula:exp_theta:plus}).
L001419	The other formula in the proposition can be checked similarly.~\qed
L001420	
L001421	\begin{proposition}
L001422	Suppose that $\theta_j(t)$ and $\theta_k(t)$
L001423	are two solutions of Eq.~(\ref{Eq:Adler})
L001424	with $\Delta = \Delta_j$ and $\Delta = \Delta_k$, respectively.
L001425	The complex parameter $H$ in Eq.~(\ref{Eq:Adler})
L001426	is assumed to be the same for both indices $j$ and $k$.
L001427	If $|\Delta_j| > |H|$ and $|\Delta_k| > |H|$, then
L001428	\begin{eqnarray*}
L001429	&&
L001430	\hspace{-7mm}
L001431	\langle e^{i \theta_j(t)} e^{-i \theta_k(t+\tau)} \rangle
L001432	- \langle e^{i \theta_j(t)} \rangle\: \langle e^{-i \theta_k(t)} \rangle
L001433	= \\[2mm]
L001434	&&
L001435	= \fr{4 \xi_j\: \mathrm{sgn}\:\Delta_j\:\xi_k\: \mathrm{sgn}\:\Delta_k}{|H|^2} \times\\[2mm]
L001436	&&
L001437	\times \sum\limits_{n,m=1}^\infty
L001438	\left( \fr{i \overline{H} e^{i \theta_j(0)} + \Delta_j - \xi_j\: \mathrm{sgn}\:\Delta_j}{i \overline{H} e^{i \theta_j(0)} + \Delta_j + \xi_j\: \mathrm{sgn}\:\Delta_j} \right)^n \times\\[2mm]
L001439	&&
L001440	\times\left( \fr{i H e^{-i \theta_k(0)} - \Delta_k + \xi_k\: \mathrm{sgn}\:\Delta_k}{i H e^{-i \theta_k(0)} - \Delta_k - \xi_k\: \mathrm{sgn}\:\Delta_k} \right)^m \times\\[2mm]
L001441	&&
L001442	\times e^{- i m \xi_k \tau\: \mathrm{sgn}\:\Delta_k}
L001443	\delta( n \xi_j\: \mathrm{sgn}\:\Delta_j - m \xi_k\: \mathrm{sgn}\:\Delta_k ),
L001444	\end{eqnarray*}
L001445	and
L001446	\begin{eqnarray*}
L001447	&&
L001448	\hspace{-7mm}
L001449	\langle e^{i \theta_j(t)} e^{i \theta_k(t+\tau)} \rangle
L001450	- \langle e^{i \theta_j(t)} \rangle\: \langle e^{i \theta_k(t)} \rangle = \\[2mm]
L001451	&&
L001452	= - \fr{4 \xi_j\: \mathrm{sgn}\:\Delta_j\:\xi_k\: \mathrm{sgn}\:\Delta_k}{\overline{H}^2} \times\\[2mm]
L001453	&&
L001454	\times \sum\limits_{n,m=1}^\infty
L001455	\left( \fr{i \overline{H} e^{i \theta_j(0)} + \Delta_j - \xi_j\: \mathrm{sgn}\:\Delta_j}{i \overline{H} e^{i \theta_j(0)} + \Delta_j + \xi_j\: \mathrm{sgn}\:\Delta_j} \right)^n \times\\[2mm]
L001456	&&
L001457	\times
L001458	\left( \fr{i \overline{H} e^{i \theta_k(0)} + \Delta_k - \xi_k\: \mathrm{sgn}\:\Delta_k}{i \overline{H} e^{i \theta_k(0)} + \Delta_k + \xi_k\: \mathrm{sgn}\:\Delta_k} \right)^m \times\\[2mm]
L001459	&&
L001460	\times e^{i m \xi_k \tau\: \mathrm{sgn}\:\Delta_k}
L001461	\delta( n \xi_j\: \mathrm{sgn}\:\Delta_j + m \xi_k\: \mathrm{sgn}\:\Delta_k ),
L001462	\end{eqnarray*}
L001463	where $\xi_j = \sqrt{\Delta_j^2 - |H|^2}$
L001464	and $\xi_k = \sqrt{\Delta_k^2 - |H|^2}$.
L001465	\label{Proposition:Covariances}
L001466	\end{proposition}
L001467	
L001468	{\bf Proof:} The above formulas are straightforward consequences
L001469	of Proposition~\ref{Proposition:Expansions}
L001470	and the identity $\langle e^{i \nu t} \rangle = \delta(\nu)$.~\qed
L001471	
L001472	\begin{remark}
L001473	If $\xi_j$ and $\xi_k$ in Proposition~\ref{Proposition:Covariances}
L001474	are incommensurable, then
L001475	$$
L001476	\langle e^{i \theta_j(t)} e^{- i \theta_k(t + \tau)} \rangle
L001477	=
L001478	\langle e^{i \theta_j(t)} \rangle\: \langle e^{- i \theta_k(t + \tau)} \rangle
L001479	$$
L001480	and
L001481	$$
L001482	\langle e^{i \theta_j(t)} e^{i \theta_k(t + \tau)} \rangle
L001483	=
L001484	\langle e^{i \theta_j(t)} \rangle\: \langle e^{i \theta_k(t + \tau)} \rangle.
L001485	$$
L001486	\end{remark}
